-- Выгрузка данных для дашборда в CSV (DataLens умеет загружать CSV-файлы). Запуск из корня репозитория:
--   psql -d m5 -f dashboard/export.sql
\copy (SELECT (DATE '2026-09-01' + (a.created_step - 1) / 24) AS day, a.route_to_be AS route, COUNT(*) AS alerts, COUNT(*) FILTER (WHERE d.is_true_positive) AS confirmed_fraud, COUNT(*) FILTER (WHERE NOT d.is_true_positive) AS false_positives, COUNT(*) FILTER (WHERE d.decided_by = 'analyst') AS analyst_alerts, ROUND(AVG(d.minutes_to_decision), 1) AS avg_minutes_to_decision FROM alerts a JOIN alert_decisions d USING (alert_id) GROUP BY 1, 2 ORDER BY 1, 2) TO 'dashboard/daily_metrics.csv' WITH (FORMAT csv, HEADER true)
\copy (SELECT r.rule_code, r.name, COUNT(h.alert_id) AS alerts, COUNT(h.alert_id) FILTER (WHERE t.is_fraud = 1) AS fraud_hits FROM alert_rules r LEFT JOIN alert_rule_hits h USING (rule_code) LEFT JOIN alerts a USING (alert_id) LEFT JOIN transactions t USING (tx_id) GROUP BY r.rule_code, r.name ORDER BY r.rule_code) TO 'dashboard/rule_hits.csv' WITH (FORMAT csv, HEADER true)
